    if(!creatingOwner&&!['driver','dispatcher'].includes(role)) throw Error('Vyberte pracovní pozici.');
    const fields=profileInput(input);
    if(fields.username.length<3) throw Error('Přihlašovací jméno musí mít alespoň 3 znaky.');
